// The wire shapes of dataflow-rs 4.0.0-dev as TypeScript: what a message, its
// context, a run, a trace and an issue serialize as. Generated by
// `tests/ts_types.rs` from the crate's types; do not edit. To regenerate:
//
//     DATAFLOW_TS_WRITE=1 cargo test --features ts --test ts_types

/**
 * Any JSON value: a payload, a context root, and the values a change holds.
 */
export type JsonValue = null | boolean | number | string | JsonValue[] | { [key: string]: JsonValue };

/**
 * A message as JSON: `{id, payload, context, audit_trail, errors}`, in that order.
 */
export type Message = {
  /**
   * The id: a UUID v7 unless set.
   */
  id: string,
  /**
   * The payload the message arrived with. It is not part of the evaluation
   * context.
   */
  payload: JsonValue,
  /**
   * The context.
   */
  context: Context,
  /**
   * The audit entries the run kept.
   */
  audit_trail: Array<AuditEntry>,
  /**
   * The errors recorded while processing.
   */
  errors: Array<ErrorRecord>,
};

/**
 * The context: `data`, `metadata` and `temp_data`, in that order. Each
 * root starts as an object; a trace's redacted root is `null`.
 */
export type Context = {
  /**
   * The `data` root.
   */
  data: JsonValue,
  /**
   * The `metadata` root.
   */
  metadata: JsonValue,
  /**
   * The `temp_data` root.
   */
  temp_data: JsonValue,
};

/**
 * One task's audit record, written as v3 wrote one.
 */
export type AuditEntry = {
  /**
   * The workflow the task belongs to.
   */
  workflow_id: string,
  /**
   * The task.
   */
  task_id: string,
  /**
   * When the entry was recorded.
   */
  timestamp: string,
  /**
   * The writes the task made, when changes are captured.
   */
  changes: Array<Change>,
  /**
   * The task's status code.
   */
  status: number,
  /**
   * The loop counter of the sweep that produced the entry.
   */
  loop_counter?: number,
  /**
   * The fan-out element the entry records.
   */
  element_index?: number,
};

/**
 * One write or removal, written as v3 wrote one.
 *
 * A path that was absent before the write records `old_value` as `null`.
 */
export type Change = {
  /**
   * The dotted path written.
   */
  path: string,
  /**
   * What the path held before; `null` when it was absent.
   */
  old_value: JsonValue,
  /**
   * The value written; `null` for a removal (read
   * `removed` to tell a removal from a write of `null`).
   */
  new_value: JsonValue,
  /**
   * The key at `path` was removed rather than written. Absent when
   * `false`, so a write's JSON is v3's.
   */
  removed?: boolean,
  /**
   * The write replaced the root at `path` instead of merging into it: a
   * host function's write at a root replaces it, and `map`'s root
   * mapping, which records only the keys it wrote, merges. A trace's
   * changes carry it, so a replay knows which; an audit entry's are
   * always `false`, so the audit trail's JSON is v3's. Absent when
   * `false`.
   */
  replaced?: boolean,
};

/**
 * One error record, written as v3 wrote one: the same keys, in the same
 * order, each optional one absent when unset. The engine stamps every
 * record a task adds with the workflow's and the task's ids and the run's
 * timestamp, keeping any the record already carries; a workflow's own
 * failure carries no task id.
 */
export type ErrorRecord = {
  /**
   * The error code.
   */
  code: string,
  /**
   * The human-readable message.
   */
  message: string,
  /**
   * Where the error happened; `null` when not known, and never absent.
   */
  path: string | null,
  /**
   * The workflow it happened in, shared with the program's own id and
   * the audit entry's, so a run allocates it once.
   */
  workflow_id?: string,
  /**
   * The task it happened in, shared as `workflow_id` is.
   */
  task_id?: string,
  /**
   * When it happened, shared with every record of the run.
   */
  timestamp?: string,
  /**
   * Operator-only detail; never to be shown to an untrusted caller.
   */
  detail?: string,
  /**
   * The fan-out element the error came from.
   */
  element_index?: number,
};

/**
 * A run's trace: `initial`, then each step's changes.
 *
 * Written as `{initial, steps, truncated}`, and read back from what it
 * writes: a trace read back writes the text it was read from, and replays
 * to the original's contexts.
 */
export type Trace = {
  /**
   * The context after the run's stamps and the error context's reset,
   * before any workflow, redacted.
   */
  initial: Context,
  /**
   * Every step, in the order the run made them.
   */
  steps: Array<TraceStep>,
  /**
   * The byte budget was crossed: from the step that crossed it on, every
   * step's changes are empty, so the contexts replayed from there on are
   * not whole.
   */
  truncated: boolean,
};

/**
 * One step of a `Trace`.
 *
 * Written with its keys in this order. `mapping_ends` and `errors` are
 * absent when empty, and `elapsed_us` (in whole microseconds),
 * `loop_counter` and `element_index` when there is none.
 * Read back from what it writes: `elapsed_us` as the whole microseconds
 * written, and an absent `mapping_ends` or `errors` as empty.
 */
export type TraceStep = {
  /**
   * The workflow's position in the program.
   */
  workflow: WorkflowIx,
  /**
   * The workflow's id.
   */
  workflow_id: string,
  /**
   * The task's position in the program; `null` for the workflow's own
   * step: its skip, its failure, or the engine's writes as a sweep is
   * entered.
   */
  task: TaskIx | null,
  /**
   * The task's id; `null` when `task` is.
   */
  task_id: string | null,
  /**
   * What the step was.
   */
  result: StepResult,
  /**
   * The call's status; `null` for a skip, a call whose outcome was a
   * skip, and the engine's step.
   */
  status: number | null,
  /**
   * The step's changes in order: the engine's writes made for it first (a
   * fan-out's `into` pre-fill), then the call's own, then the progress
   * write, then the error context's. Empty past the byte budget and when
   * the trace records none.
   */
  changes: Array<Change>,
  /**
   * Where each of a `map`'s mappings ends in `changes`: one entry per
   * mapping, in order, the index just past its last change, so mapping
   * `i`'s changes run from the end before it (0 for the first) up to its
   * own. A mapping that wrote nothing repeats the end before it.
   * Replaying the changes before mapping `i`'s end gives the context
   * after mapping `i`. Empty for every other step, and whenever `changes`
   * is.
   */
  mapping_ends?: Array<number>,
  /**
   * Every record the step added to the message, in the message's order:
   * the call's own, then the engine's; for a workflow's own failure, its
   * record. A workflow whose condition failed to evaluate adds none to
   * the message, and its `skipped` step holds that failure's record.
   */
  errors?: Array<ErrorRecord>,
  /**
   * How long the call ran, written in whole microseconds, when the trace
   * asked for timings.
   */
  elapsed_us?: number,
  /**
   * The loop counter of the sweep: the call's, or the one the engine's
   * step wrote.
   */
  loop_counter?: number,
  /**
   * The fan-out element the call ran for.
   */
  element_index?: number,
};

/**
 * What a step was. Serialized, and read, as its lowercase name.
 */
export type StepResult = "executed" | "skipped" | "failed";

/**
 * The position of a workflow within a program. Serialized as its number,
 * and read from one.
 */
export type WorkflowIx = number;

/**
 * The position of a task within a program. Serialized as its number, and
 * read from one: a position read back names a task only in the program
 * that wrote it.
 */
export type TaskIx = number;

/**
 * A run as JSON: how it ended and what each workflow did. Neither the trace
 * nor the arena counters are part of it.
 */
export type Run = {
  /**
   * How the run ended.
   */
  status: RunStatus,
  /**
   * The error that stopped the run; present only when `status` is `stopped`.
   */
  error?: DataflowError,
  /**
   * May running the message again succeed? True for a timeout and for a
   * stop whose error says so.
   */
  retryable: boolean,
  /**
   * Did the run end before every workflow was considered?
   */
  partial: boolean,
  /**
   * How many workflows were selected and ran.
   */
  matched: number,
  /**
   * Every workflow considered, in program order, up to and including the
   * one that stopped the run.
   */
  workflows: Array<WorkflowRecord>,
};

/**
 * How a run ended: a stopped run's error is its `error`.
 */
export type RunStatus = "completed" | "completed_with_errors" | "stopped" | "timed_out" | "cancelled";

/**
 * One workflow's part in a run.
 */
export type WorkflowRecord = {
  /**
   * The workflow's id.
   */
  id: string,
  /**
   * The workflow's position in the program.
   */
  index: WorkflowIx,
  /**
   * Whether it was selected.
   */
  selection: Selection,
  /**
   * Why its condition failed to evaluate; present only when `selection` is
   * `condition_failed`.
   */
  error?: DataflowError,
  /**
   * The sweeps begun: one for a workflow without a loop that ran, and for
   * a loop each sweep its condition admitted.
   */
  sweeps: number,
  /**
   * How it ended; `null` when it did not run.
   */
  exit: WorkflowExit | null,
};

/**
 * Why a workflow did or did not run: a failed condition's error is its
 * record's `error`.
 */
export type Selection = "ran" | "skipped_by_condition" | "condition_failed" | "skipped_by_rollout";

/**
 * How a workflow that ran ended.
 */
export type WorkflowExit = "completed" | "halted" | "failed" | "stopped";

/**
 * An error as JSON: its code, its message, and whether a retry may
 * succeed.
 */
export type DataflowError = {
  /**
   * The recorded code.
   */
  code: string,
  /**
   * The human-readable message.
   */
  message: string,
  /**
   * May a retry succeed?
   */
  retryable: boolean,
};

/**
 * One finding about an authored definition.
 *
 * It serializes as an object of its seven fields, under their own names: the
 * code and severity as their strings, the path as it displays, the step kind
 * as `task`, `group` or `setup`, and an absent part as `null`.
 */
export type Issue = {
  /**
   * What it is about.
   */
  code: IssueCode,
  /**
   * When it bites: its code's own severity, unless the host overrode it.
   */
  severity: Severity,
  /**
   * Where in the authored JSON.
   */
  path: AuthoredPath,
  /**
   * The kind of step it sits in, if any.
   */
  step_kind: StepKind | null,
  /**
   * The id of the step it sits in, if known.
   */
  step_id: string | null,
  /**
   * The config field (the first key under `function.input`), if inside one.
   */
  field: string | null,
  /**
   * A human-readable explanation.
   */
  message: string,
};

/**
 * What an issue is about: its SCREAMING_SNAKE code, such as `UNKNOWN_FUNCTION`.
 */
export type IssueCode = "EMPTY_WORKFLOW_ID" | "NO_TASKS" | "MISSING_STEP_ID" | "DUPLICATE_STEP_ID" | "EMPTY_GROUP" | "GROUP_TOO_DEEP" | "MISSING_FUNCTION" | "INVALID_FUNCTION_NAME" | "INVALID_TERMINAL" | "UNGUARDED_VALIDATION" | "INVALID_HALT_ON" | "GROUP_CONTINUE_ON_ERROR" | "INVALID_MAPPING" | "NULL_MAPPING" | "LOOP_INCREMENT_TOO_SMALL" | "LOOP_BOUND_EMPTY" | "LOOP_COUNTER_INVALID" | "LOOP_SLOT_INVALID" | "LOOP_ITEM_WITHOUT_OVER" | "LOOP_SLOT_COLLISION" | "LOOP_OVER_INVALID" | "INVALID_FOR_EACH" | "UNKNOWN_FUNCTION" | "INPUT_PARSE" | "TEMPLATE_COMPILE" | "UNKNOWN_SECRET" | "SECRET_IN_MESSAGE_WRITE" | "DUPLICATE_TEMPLATE_KEY" | "ESCAPED_TEMPLATE_KEY" | "PARSE_FAILED" | "MIXED_SPELLING" | "EXT_COLLISION" | "LIKELY_TYPO" | "UNKNOWN_KEY" | "V3_SPELLING" | "NULL_CONDITION" | "PAYLOAD_VAR" | "OPERATOR_IN_DOCUMENT" | "SECRET_IN_DOCUMENT" | "INVALID_PATH" | "UNRESOLVED_REFERENCE" | "INVALID_ROLLOUT";

/**
 * When an issue bites.
 */
export type Severity = "REJECTED" | "DEFECT" | "ADVISORY";

/**
 * What kind of step an issue sits in.
 */
export type StepKind = "task" | "group" | "setup";

/**
 * A path in the authored JSON, as v3 spelled it: `tasks[1].tasks[0].id`.
 * The document itself is the empty string.
 */
export type AuthoredPath = string;
